function storedJson<T>(key:string,fallback:T):T{try{const value=localStorage.getItem(key);return value?JSON.parse(value) as T:fallback}catch{return fallback}}
function withoutRepeatedSummary(story:Story):Story{const full=(story.full||"").trim();if(!full.startsWith(story.summary))return story;return{...story,full:full.slice(story.summary.length).replace(/^[。；;，,\s]+/,"").trim()}}
const todayStories:Story[]=[
{id:"ai-1",section:"AI",kicker:"今日首选 · 8月14日",title:"Claude 将为生成文本加入不可见水印",summary:"Anthropic 公布文本水印方案：不添加隐藏字符、不增加 token，并计划推出检测 API。",full:"Anthropic 8 月 14 日宣布，未来 Claude 模型生成的文本将包含不可见水印，以满足欧盟《人工智能法案》关于生成内容标记的要求。它采用 SynthID-Text 路线，不是在文字里塞入隐藏字符，而是在模型面对多个同样合理的下一个词时，用密钥控制随机选择，从而留下可统计检测的模式。\n\nAnthropic 表示，水印不会增加 token、不会提高价格，也不会携带用户、组织或对话身份。短文本、事实性文字、代码和轻度校对的可检测性会更弱，完整改写也可能移除水印。公司计划提供检测 API。\n\n为什么重要：生成内容的“来源证明”开始从倡议进入模型默认能力。对内容平台和企业来说，水印只能说明 AI 可能参与过，不能独立证明作者身份或内容真伪，因此仍需配合 C2PA、审计记录和人工核验。",source:"Anthropic",url:"https://www.anthropic.com/news/claude-text-watermark",time:"7 分钟"},
{id:"ai-2",section:"AI",kicker:"Agent · 8月12日",title:"企业 AI 正从“回答问题”转向“直接执行工作”",summary:"OpenAI 的两项研究显示，领先企业更频繁地把 AI 接入工具、上下文和可重复工作流。",full:"OpenAI 8 月 12 日发布两项企业使用研究。其数据表明，AI 在企业中的使用正在从辅助思考转向完成多步骤工作。按每位活跃用户的输出量衡量，使用最深入的前 10% 企业，是典型企业的 8.3 倍；这一差距在 1 月时为 2.6 倍。\n\n截至 6 月，Codex 在企业客户的 Codex 与 ChatGPT 合计输出 token 中占 64%。自 2 月以来，企业 Codex 周活跃用户在法律、销售、招聘和市场岗位上的增长，明显快于工程岗位。\n\n产品启发：模型能力只是起点。真正拉开差距的是能否接入企业上下文和工具，并建立权限、人工复核、治理与可复制的团队工作流。",source:"OpenAI",url:"https://openai.com/index/how-enterprises-put-ai-to-work/",time:"8 分钟"},
{id:"ai-3",section:"AI",kicker:"开放模型 · 8月10日",title:"Meta 发布可在个人电脑运行的 Muse Glimmer",summary:"Meta 再次押注开放模型，并提出让个人拥有通用 AI 助手的长期愿景。",full:"据美联社报道，Meta 8 月 10 日发布新的开放模型 Muse Glimmer，可在个人电脑上运行，同时向开发者提供更强的 Muse Spark 1.2。Mark Zuckerberg 在一篇长文中提出，未来每个人都可能拥有帮助学习、创业和生活决策的个人 AI。\n\n这次发布的重点不只是模型分数，而是“足够强、成本更低、可本地运行”的组合。它让隐私敏感、离线和低成本应用获得更多选择，也重新加剧开放权重与封闭前沿模型之间的竞争。\n\n需要继续观察：模型真实能力、许可证边界、端侧资源占用和安全评测，仍要以技术报告和独立测试为准。",source:"Associated Press",url:"https://apnews.com/article/meta-ai-mark-zuckerberg-artificial-intelligence-df8a4e7d7825470d09e8090367457c2c",time:"6 分钟"},
{id:"ai-4",section:"AI",kicker:"产业观察 · 8月13日",title:"模型竞争进入“能力 × 价格”的新阶段",summary:"新模型以更低成本逼近前沿水平，市场选择开始从单一榜单转向综合性价比。",full:"Axios 8 月 13 日报道，SpaceX 与 Meta 本周推出的新模型，在性能与价格的组合上对前沿实验室形成新的压力。报道援引 Artificial Analysis 指标称，Grok 4.6 的综合表现接近当时的头部系统；Meta 则以可在笔记本运行的开放模型从成本端切入。\n\n这意味着模型采购不能只看最高分。对绝大多数产品，响应速度、推理成本、上下文长度、可部署位置、稳定性和许可证，都会与纯能力一起决定最终价值。\n\n我们的判断：未来更常见的架构是模型路由——高频简单任务交给便宜模型，困难或高风险任务再升级到前沿模型。",source:"Axios",url:"https://www.axios.com/2026/08/13/grok-elon-musk-ai-zuckerberg-and-meta",time:"6 分钟"},
{id:"ai-5",section:"AI",kicker:"研究 · 7月23日",title:"Google 用 1500 万次交互观察真实世界如何使用 AI",summary:"ATLAS 研究覆盖 150 多个国家：AI 目前更多是协作工具，完全自动化仍然少见。",full:"Google 的 ATLAS v1.0 基于 Gemini App、AI Mode 和 Gemini API 中 1500 万次聚合、去标识化交互，覆盖 150 多个国家、140 种语言、800 个职业和 4000 类任务。\n\n研究显示，AI 已覆盖美国约 68% 的职业，但在典型岗位中只用于约 21% 的任务；工作场景主要是构思、检索、学习和协作，完全自动完成的交互不到 10%。AI 也在帮助汽车技师和工业机械师等职业进行诊断和现场学习。\n\n为什么重要：现实中的 AI 采用并不是一次性替代整个岗位，而是先渗透到具体任务。产品应围绕工作步骤设计，而不是只围绕职业标签或笼统的“自动化”叙事。",source:"Google",url:"https://blog.google/innovation-and-ai/technology/research/understanding-the-ai-economy/",time:"8 分钟"},
{id:"emb-1",section:"具身智能",kicker:"World Model · Paper Radar",title:"AlayaWorld v1.1 让生成世界拥有更长期的空间记忆",summary:"约 15B 参数的视频世界模型用流式 3D 点缓存减少长时间交互中的空间漂移。",full:"AlayaWorld v1.1 试图解决世界模型最关键的工程问题之一：不是生成几秒钟好看的视频，而是让环境在持续交互后仍保持空间一致。团队引入 Streaming 3D Point Cache Renderer，并让视觉条件与生成视频共享更一致的潜表示和时间结构。\n\n它连接了游戏生成、机器人训练、自动驾驶模拟与 Physical AI。当前结果来自新预印本，仍需等待独立复现与真实系统评测。",source:"arXiv",url:"https://arxiv.org/abs/2608.13492",time:"8 分钟"},
{id:"tech-1",section:"科技",kicker:"全球科技 TOP 5 · 算力",title:"NVIDIA 推动超 5000 亿美元 AI 算力融资体系",summary:"GPU、数据中心合同与未来算力收入正在被组织成可以融资的基础设施资产。",full:"Reuters 8 月 14 日报道，NVIDIA 正与 Apollo、BlackRock、Blackstone、Brookfield、Goldman Sachs、KKR 等机构合作推动 AI Compute Financing，潜在规模超过 5000 亿美元。\n\nNVIDIA 的角色正在从单纯卖芯片扩展为帮助客户和数据中心获得融资。如果这种模式跑通，算力可能像飞机、电站和房地产一样，依靠长期租赁现金流进行再融资；风险则是模型效率快速提升或需求不足导致资产利用率下降。",source:"Reuters",url:"https://www.reuters.com/legal/transactional/private-credit-roundup-nvidias-half-trillion-chips-financing-plus-others-2026-08-14/",time:"7 分钟"},
{id:"news-1",section:"新闻",kicker:"世界 TOP 5 · AI治理",title:"欧盟生成式 AI 透明度要求开始进入模型默认能力",summary:"主要模型提供商开始落实生成内容标记，AI 治理从原则逐步进入产品实现。",full:"Anthropic 表示将为未来 Claude 模型生成的文本加入水印，以遵循欧盟生成内容透明度要求。约 190 个签署方参与相关实践准则。\n\n这件事的影响超出单一产品：生成内容标记、检测接口、文件内容凭证和平台披露机制将逐步组成新的数字内容基础设施。但水印只能表示 AI 可能参与，不能代替事实核查。",source:"Anthropic",url:"https://www.anthropic.com/news/claude-text-watermark",time:"6 分钟"}];
