function beijingIsoDate(){const parts=new Intl.DateTimeFormat("en-US",{year:"numeric",month:"2-digit",day:"2-digit",timeZone:"Asia/Shanghai"}).formatToParts(new Date()),value=(type:string)=>parts.find(part=>part.type===type)?.value||"";return`${value("year")}-${value("month")}-${value("day")}`}
function shiftIsoDate(iso:string,days:number){const date=new Date(`${iso}T00:00:00Z`);date.setUTCDate(date.getUTCDate()+days);return date.toISOString().slice(0,10)}
function monthStart(iso:string){return`${iso.slice(0,7)}-01`}
const currentDateIso=beijingIsoDate(),calendarMax=currentDateIso,calendarMin=shiftIsoDate(currentDateIso,-29),calendarFirstMonth=monthStart(calendarMin),calendarLastMonth=monthStart(calendarMax),calendarAvailableMonths=calendarFirstMonth===calendarLastMonth?[calendarLastMonth]:[calendarFirstMonth,calendarLastMonth];
const dates=Array.from({length:30},(_,index)=>{const iso=shiftIsoDate(currentDateIso,-index),date=new Date(`${iso}T00:00:00Z`),display=`${date.getUTCMonth()+1}月${date.getUTCDate()}日`;return{key:index===0?"today":iso,label:index===0?"今天":index===1?"昨天":index===2?"前天":display,sub:index<3?display:weekdays[date.getUTCDay()]}});
