todayStories.push({id:"science-1",section:"前沿科学",kicker:"数学 · AI for Science",title:"AI 解出 Erdős 数学问题，也引发证明核验与署名讨论",summary:"结果本身得到认可，但过程暴露出 AI 科研时代关于复核、开放性和贡献归属的新问题。",full:"AI 系统参与解决一个 Erdős 数学问题后，数学界关注的不只是答案正确与否，也包括证明是否可以独立检查、训练材料如何引用、人的贡献如何确认。\n\n这类案例说明 AI for Science 的评价需要同时覆盖结果、过程可追溯性、复现和学术信用，而不能只看最终解答。",source:"Science News",url:"https://www.sciencenews.org/article/ai-erdos-math-problem-guardrails",time:"7 分钟"});
todayStories.push(
{id:"emb-2",section:"具身智能",kicker:"World Foundation Model",title:"Xiaomi-Robotics-U0 把世界模型变成机器人数据引擎",summary:"38B 多模态模型统一生成多视角场景、机器人迁移和具身视频。",full:"Xiaomi-Robotics-U0 把具身生成视为图像与视频基础模型的扩展，同时训练文本生成图像、编辑、具身场景、多本体迁移和视频生成。论文报告称，它在困难真实操作任务中把 π0.5 的分布外成功率从 36.9% 提升到 63.2%。\n\n这条路线的价值是用世界模型生成结构一致的训练数据，降低真实机器人采集成本。结果仍应结合公开代码、检查点和第三方复现判断。",source:"arXiv",url:"https://arxiv.org/abs/2607.11643",time:"8 分钟"},
{id:"emb-3",section:"具身智能",kicker:"Physical AI · 产业",title:"Unitree 的资本热度反映人形机器人进入规模化验证期",summary:"市场开始用收入、海外销售和制造能力，而不只是 Demo 评价机器人公司。",full:"8 月中旬市场对 Unitree 上市进程的高关注，显示 Physical AI 正从实验室展示进入资本、供应链和规模制造阶段。值得看的不是短期申购热度，而是机器人企业是否能持续交付、采集高质量数据并形成软硬件闭环。\n\n后续应持续跟踪 VLA、World Model、Sim2Real、可靠性和单位成本。",source:"Reuters",url:"https://www.reuters.com/world/asia-pacific/what-is-unitree-why-are-chinas-humanoid-robot-makers-racing-list-2026-08-10/",time:"7 分钟"},
{id:"emb-4",section:"具身智能",kicker:"系统安全",title:"具身智能落地的核心不只能力，还有全生命周期安全",summary:"真实机器人必须同时处理感知误差、控制风险、人机协作和持续治理。",full:"SAE World Congress 2026 的具身智能白皮书把安全、信任、机器人和真实部署放在同一系统框架下。其核心观点是，具身 AI 不能只按模型指标管理，而应覆盖设计、验证、部署、监控和事故响应全生命周期。\n\n对企业产品，权限边界、紧急停止、仿真测试、可解释日志和人类监督应从第一天进入架构。",source:"arXiv / SAE",url:"https://arxiv.org/abs/2605.10653",time:"7 分钟"},
{id:"emb-5",section:"具身智能",kicker:"学习路线 · ROS 2",title:"ROS 2 仍是连接 VLA、规划、控制与硬件的重要工程层",summary:"模型负责理解和决策，ROS 2 负责把感知、动作与真实设备组织成系统。",full:"VLA 与世界模型并不会取代机器人中间件。ROS 2 的节点、主题、服务和动作机制，仍承担传感器数据流、硬件驱动、长任务反馈和模块隔离。\n\n建议学习顺序：ROS 2 基础 → 仿真 → 导航与机械臂 → 感知规划控制闭环 → 接入 VLA → 真机安全与部署。",source:"ROS Documentation",url:"https://docs.ros.org/",time:"9 分钟"},
{id:"tech-2",section:"科技",kicker:"全球科技 TOP 5 · 芯片",title:"NVIDIA 披露对 SpaceX 的约 210 亿美元持仓",summary:"AI 芯片、云计算与航天基础设施之间的资本联系进一步加深。",full:"公开监管披露显示，NVIDIA 在二季度末持有规模可观的 SpaceX 投资。它反映的不只是财务投资，还体现 AI 训练、卫星网络、数据中心和算力需求之间越来越紧密的产业关系。\n\n需要区分战略协同与估值风险：交叉持股不会自动带来收入，仍要观察真实采购、利用率与现金流。",source:"SEC",url:"https://www.sec.gov/edgar/search/",time:"5 分钟"},
{id:"tech-3",section:"科技",kicker:"全球科技 TOP 5 · 开源",title:"Meta 推出可在个人电脑运行的 Muse Glimmer",summary:"开放权重、本地运行和低成本成为前沿能力之外的关键竞争维度。",full:"Meta 发布 Muse Glimmer，并计划向开发者提供更强的 Muse Spark 1.2。可在个人设备运行意味着更低延迟、更多隐私控制和离线场景，也让企业能够在云端前沿模型与本地开放模型之间进行路由。\n\n实际采用仍要核对许可证、硬件占用、评测和安全边界。",source:"Associated Press",url:"https://apnews.com/article/meta-ai-mark-zuckerberg-artificial-intelligence-df8a4e7d7825470d09e8090367457c2c",time:"6 分钟"},
{id:"tech-4",section:"科技",kicker:"全球科技 TOP 5 · 企业软件",title:"Agent 正快速进入法律、销售、招聘与市场岗位",summary:"企业 AI 的下一阶段是把个人技巧沉淀成团队可复用的工作流。",full:"OpenAI 的企业研究显示，自 2 月以来 Codex 在法律、销售、招聘和市场岗位的周活增长明显。领先企业更频繁使用连接上下文、工具和技能的能力。\n\n这意味着企业软件会从“每个页面加聊天框”转向任务编排、权限、复核和审计。",source:"OpenAI",url:"https://openai.com/index/how-enterprises-put-ai-to-work/",time:"7 分钟"},
{id:"tech-5",section:"科技",kicker:"全球科技 TOP 5 · 数字经济",title:"Google ATLAS 显示 AI 已覆盖大量职业，但自动化仍较浅",summary:"真实使用主要集中于构思、检索、学习和协作，完整自动化不到一成交互。",full:"ATLAS v1.0 覆盖 1500 万次去标识化交互、150 多个国家和 800 个职业。数据表明 AI 的扩散很广，但典型岗位只在部分任务中使用。\n\n对科技产业而言，这意味着增长空间来自更深的工作流集成，而不只是新增用户。",source:"Google",url:"https://blog.google/innovation-and-ai/technology/research/understanding-the-ai-economy/",time:"7 分钟"},
{id:"science-2",section:"前沿科学",kicker:"AI for Science · arXiv",title:"OmniScientist 让 AI 直接读取视频、音频、3D 和原始实验数据",summary:"三个 Agent 分别承担构思、实验和写作，并用确定性程序检查统计与数字一致性。",full:"OmniScientist 试图把 AI Scientist 从读论文、写代码扩展到直接理解原始科研证据。论文在五大学科、36 个真实数据案例中测试了从数据到论文的完整流程，并报告直接感知原始数据的版本在多项指标上更好。\n\n这是新预印本，85% 两两比较胜率等结果仍需独立验证，但“多模态科学 Agent”方向值得长期跟踪。",source:"arXiv",url:"https://arxiv.org/abs/2608.13558",time:"9 分钟"},
{id:"science-3",section:"前沿科学",kicker:"量子计算 · Nature",title:"自旋量子比特取得多项关键进展",summary:"四个独立团队在误差率和器件能力上推进了被低估的自旋量子路线。",full:"Nature 近期汇总多项自旋量子比特研究。自旋量子比特有望利用半导体制造基础设施扩大规模，但仍面临控制、读出、噪声和大规模互连问题。\n\n判断量子突破时，应关注逻辑错误率、可扩展制造和系统级演示，而不只看单个器件纪录。",source:"Nature",url:"https://www.nature.com/articles/d41586-026-02400-7",time:"7 分钟"},
{id:"science-4",section:"前沿科学",kicker:"生命科学 · Nature",title:"新型 CRISPR 酶尝试精准破坏携带癌症突变的细胞",summary:"早期实验探索把能切碎 DNA 的蛋白定向到肿瘤突变。",full:"这项研究探索利用特殊 CRISPR 相关酶识别肿瘤突变并破坏细胞 DNA。当前仍属于早期验证，距离临床需要解决脱靶、递送、免疫反应和正常组织安全等问题。\n\n真正重要的是基因编辑工具正从“修改一个位点”扩展到更多可编程治疗机制。",source:"Nature",url:"https://www.nature.com/news",time:"6 分钟"},
{id:"science-5",section:"前沿科学",kicker:"公共卫生 · Nature",title:"古 DNA 提供天花传入美洲的直接基因证据",summary:"智利木乃伊中的病毒序列支持疾病由欧洲人带入的历史判断。",full:"研究人员从历史遗骸中恢复病毒基因信息，为天花进入美洲的时间与传播来源提供直接证据。古病原体基因组能够补充文献记录，并帮助研究疾病、迁徙和社会变化之间的关系。\n\n此类研究同时要求严格处理样本污染、年代测定和伦理问题。",source:"Nature",url:"https://www.nature.com/articles/d41586-026-02452-9",time:"6 分钟"},
{id:"science-6",section:"前沿科学",kicker:"化学与公共安全",title:"机器学习尝试预测超过十亿种潜在芬太尼变体的化学指纹",summary:"研究目标是让检测系统识别尚未被目录收录的新型合成阿片。",full:"研究人员使用机器学习预测大量可能芬太尼变体的质谱等化学特征，以应对新型物质变化快、标准品不足的问题。\n\n该方法的价值在于扩大筛查范围，但实际执法和医疗判断仍需实验室确认、误报评估与标准化流程。",source:"Science News",url:"https://www.sciencenews.org/article/fentanyl-variants-machine-learning",time:"7 分钟"}
);
