 const fallbackToday=[...todayStories,...Object.values(archives).flat()]; const liveToday=liveContent?.today||[]; const missingTodaySections=new Set(["AI","具身智能","科技","前沿科学","新闻"].filter(section=>!liveToday.some(story=>story.section===section))); const contentToday=[...liveToday,...fallbackToday.filter(story=>missingTodaySections.has(story.section))].filter((story,index,all)=>all.findIndex(item=>item.id===story.id)===index); const contentArchives=liveContent?.archives||archives;const recentArchiveEntries=Object.entries(contentArchives).filter(([date])=>date>=calendarMin&&date<calendarMax);const datedEntries:[string,Story[]][]=[[calendarMax,contentToday],...recentArchiveEntries];const filteredDatedEntries=appliedDateFrom?datedEntries.filter(([date])=>date>=appliedDateFrom&&date<=appliedDateTo):datedEntries;const all=selectedDate==="today"?contentToday:contentArchives[selectedDate]||[];const rangeStories=appliedDateFrom?filteredDatedEntries.flatMap(([,stories])=>stories):all;const scopedAll=active==="收藏"?favorites:active==="今日"?contentToday:rangeStories;const shown=active==="收藏"?favorites:scopedAll.filter(s=>active==="今日"||s.section===active);const selected=dates.find(d=>d.key===selectedDate)||dates[0];const index=active==="今日"?[{date:"today",stories:contentToday}]:active==="收藏"?[{date:"收藏",stories:favorites}]:filteredDatedEntries.map(([date,stories])=>({date,stories}));const results=query.trim()?index.flatMap(g=>g.stories.filter(s=>`${s.section} ${s.kicker} ${s.title} ${s.summary} ${s.full||""}`.toLowerCase().includes(query.trim().toLowerCase())).map(story=>({date:g.date,story}))):[];
 function jump(date:string,story:Story){setSelectedDate(date);setActive(story.section==="大模型知识"?"AI":story.section);setExpanded(story.id);setSearchOpen(false);setQuery("");setTimeout(()=>document.querySelector("article.open")?.scrollIntoView({behavior:"smooth",block:"center"}),150)}
 const knowledgeCard=liveContent?.knowledge?{title:liveContent.knowledge.title,tag:"每日大模型知识 · 自动更新",intro:liveContent.knowledge.summary,full:liveContent.knowledge.full||"",source:liveContent.knowledge.source,url:liveContent.knowledge.url}:aiKnowledge;
 const knowledgeParagraphs=("full" in knowledgeCard?knowledgeCard.full:knowledgeCard.points.join("\n\n")).split("\n").filter(Boolean);
 const knowledgeView=<> {selectedDate==="today"&&(active==="今日"||active==="AI")&&<section className={`knowledge ${knowledgeOpen?"expanded":""}`}><div className="knowledge-label"><span>大模型核心知识</span><div className="knowledge-label-actions"><small>{knowledgeCard.tag}</small><button className="knowledge-expand" aria-label={knowledgeOpen?"收起大模型核心知识":"展开大模型核心知识"} onClick={()=>setKnowledgeOpen(!knowledgeOpen)}>{knowledgeOpen?<ChevronUp size={18}/>:<ChevronDown size={18}/>}</button></div></div><div className="knowledge-main"><div><h2>{knowledgeCard.title}</h2><p>{knowledgeCard.intro}</p></div></div>{knowledgeOpen&&<div className="knowledge-course">{knowledgeParagraphs.map((paragraph,index)=><p key={`${index}-${paragraph}`}>{paragraph}</p>)}</div>}<div className="knowledge-foot"><button onClick={()=>setKnowledgeOpen(!knowledgeOpen)}>{knowledgeOpen?"收起课程":"阅读全文"}</button><a href={knowledgeCard.url} target="_blank" rel="noreferrer">原始论文与技术资料 · {knowledgeCard.source} ↗</a></div></section>} </>; const feedView=(<section className="feed"><div className="section-head"><div><p className="eyebrow">{active==="收藏"?"MY LIBRARY":active==="AI"&&selectedDate==="today"?"GLOBAL AI DAILY 5":`${selected.sub} · ARCHIVE`}</p><h2>{active==="今日"?"值得关注":active==="AI"&&selectedDate==="today"?"全球 AI 每日 5 件事":active}</h2></div><p>{shown.length} 篇站内全文</p></div>{active==="收藏"&&!shown.length&&<div className="empty-state"><Bookmark/><h3>还没有收藏</h3><p>点击文章右侧的书签即可保存。</p></div>}{shown.map((s,i)=>{const open=expanded===s.id,starred=favorites.some(f=>f.id===s.id),note=briefingNotes[s.id],articleText=`${s.title}。${s.summary}。${s.full||""}`;return <article id={`story-${s.id}`} className={open?"open":""} key={s.id}><div className="story-lead"><div className="story-number">{String(i+1).padStart(2,"0")}</div><button className="story-read" aria-label={`朗读：${s.title}`} title="朗读文章" onClick={()=>beginArticleReading(articleText)}><Volume2 size={16}/></button></div><div className="story-body">{s.image&&<img className="story-image" src={s.image} alt="" loading="lazy" onError={e=>{e.currentTarget.style.display="none"}}/>}<p className="kicker">{s.section} · {s.kicker}</p><button className="story-toggle" onClick={()=>setExpanded(open?null:s.id)}><h3>{s.title}</h3>{open?<ChevronUp/>:<ChevronDown/>}</button><p className="summary">{s.summary}</p><div className="full-text">{(s.full||"").split("\n").map((p,j)=>p&&<p key={j}>{p}</p>)}{note&&<><div className="editor-note"><h4>为什么重要？ <b>{note.rating}</b></h4><p>{note.why}</p></div><div className="editor-note insight"><h4>产品启发</h4><p>{note.insight}</p></div></>}<div className="source-note"><span>原始来源</span><a href={s.url} target="_blank" rel="noreferrer">{s.source} ↗</a></div></div><div className="meta"><span>{s.time} 阅读</span><div className="actions"><button aria-label="收藏" className={starred?"selected favorite":""} onClick={()=>favorite(s)}><Bookmark size={16} fill={starred?"currentColor":"none"}/></button><button aria-label="分享" onClick={()=>share(s)}><Share2 size={16}/></button><button aria-label="喜欢" className={votes[s.id]===1?"selected":""} onClick={()=>vote(s.id,1)}><ThumbsUp size={16}/></button><button aria-label="不喜欢" className={votes[s.id]===-1?"selected down":""} onClick={()=>vote(s.id,-1)}><ThumbsDown size={16}/></button></div></div></div></article>})}{active==="AI"&&selectedDate==="today"&&<div className="briefing-summary"><p className="eyebrow">TODAY'S SIGNAL</p><h3>今天最值得记住的三条线</h3><p><b>开放权重</b>正在上升为企业与国家级技术路线；<b>Agent</b>从回答走向完整工作流；<b>AI 基础设施</b>开始同时由算法、芯片、部署和金融成本驱动。</p></div>}</section>);
 return <main className={!dateOpen&&!appliedDateFrom&&active!=="今日"&&active!=="收藏"?"date-browse":""}><header><a className="brand" href="#top">Stellar AI</a><nav>{nav.map(n=><button className={active===n?"active":""} onClick={()=>{const daily=n!=="今日"&&n!=="收藏";setActive(n);setDateOpen(daily);if(n!=="收藏")setSelectedDate("today");setAppliedDateFrom("");setAppliedDateTo("");setDateFrom("");setDateTo("");setCalendarOpen(false)}} key={n}>{createElement(navIcons[n],{size:18,strokeWidth:1.8})}<span>{n}</span></button>)}</nav><button className="install" onClick={installApp}><Download size={16}/>安装 App</button>{isAdmin&&<button className="account-btn" onClick={()=>setAccountOpen(true)}><UserRoundPlus size={16}/>账号</button>}<button className="avatar" onClick={async()=>{await fetch("/api/logout",{method:"POST"});setLoggedIn(false)}}>LY</button></header>{accountOpen&&<div className="modal-backdrop" onClick={()=>setAccountOpen(false)}><section className="account-modal" onClick={e=>e.stopPropagation()}><button className="modal-close" onClick={()=>setAccountOpen(false)}><X/></button><UserRoundPlus className="modal-icon"/><h2>新增登录账号</h2><p>新账号可以独立登录、收藏和使用兴趣反馈。</p><form onSubmit={addAccount}><label>账号<input name="username" minLength={3} maxLength={24} required/></label><label>密码<input name="password" type="password" minLength={8} required/></label><button>创建账号</button></form></section></div>}
 <section className="hero" id="top"><div className="hero-top"><img src="./icon-192.png" alt=""/><p className="date">{selectedDate==="today"?`${today} · 北京`:`${selected.sub} · 历史归档`}</p></div><h1>{active==="今日"?<>今天，有什么<br/><em>值得知道？</em></>:<>{active}<br/><em>每日精选</em></>}</h1><p className="intro">完整中文内容已缓存在站内。来源链接仅用于核验，阅读无需离开 Stellar AI。</p><div className="pulse"><i/> 内容已归档 <span>02:16</span></div></section>
 <section className="search-wrap"><div className="search-box"><Search size={19}/><input value={query} onFocus={()=>setSearchOpen(true)} onChange={e=>{setQuery(e.target.value);setSearchOpen(true)}} placeholder={active==="今日"?"搜索今天内容，例如 ROS":active==="收藏"?"搜索已收藏内容":"搜索近一个月内容，例如 ROS"}/>{appliedDateCompactLabel&&active!=="今日"&&active!=="收藏"&&<div className="search-date-value"><span>{appliedDateCompactLabel}</span><button aria-label="清除已选日期" onClick={()=>{setAppliedDateFrom("");setAppliedDateTo("");setDateFrom("");setDateTo("");setSelectedDate("today");setDateOpen(true);calendarDragStartRef.current="";calendarAwaitingEndRef.current=false}}><X size={14}/></button></div>}{active!=="今日"&&active!=="收藏"&&<button className={`calendar-trigger ${appliedDateFrom?"active":""}`} aria-label="选择日期" onClick={()=>{if(!calendarOpen){setDateFrom(appliedDateFrom);setDateTo(appliedDateTo);calendarDragStartRef.current="";calendarAwaitingEndRef.current=false}setCalendarOpen(!calendarOpen);setSearchOpen(false)}}><CalendarDays size={19}/></button>}{query&&<button onClick={()=>setQuery("")}><X size={17}/></button>}</div>{calendarOpen&&active!=="今日"&&active!=="收藏"&&<section className="calendar-popover"><header><button aria-label="上一个月" disabled={calendarMonth==="2026-07-01"} onClick={()=>setCalendarMonth("2026-07-01")}><ChevronLeft size={18}/></button><b>{dateFrom?`${dateFrom}${dateTo&&dateTo!==dateFrom?` 至 ${dateTo}`:""}`:"选择日期"}</b>{dateFrom&&<button aria-label="清除日期" onClick={()=>{setDateFrom("");setDateTo("");calendarDragStartRef.current="";calendarAwaitingEndRef.current=false}}><X size={16}/></button>}<button aria-label="下一个月" disabled={calendarMonth==="2026-08-01"} onClick={()=>setCalendarMonth("2026-08-01")}><ChevronRight size={18}/></button></header><div className={`calendar-months ${showTwoCalendarMonths?"two":""}`}>{calendarMonths.map(renderCalendarMonth)}</div><footer className="calendar-actions"><button onClick={()=>{setDateFrom(appliedDateFrom);setDateTo(appliedDateTo);setCalendarOpen(false);calendarDragStartRef.current="";calendarAwaitingEndRef.current=false}}>取消</button><button className="confirm" onClick={()=>{setAppliedDateFrom(dateFrom);setAppliedDateTo(dateTo||dateFrom);setDateOpen(false);setCalendarOpen(false);calendarDragStartRef.current="";calendarAwaitingEndRef.current=false}}>确定</button></footer></section>}{searchOpen&&query&&<div className="search-results"><div className="search-count">2026 年 · 找到 {results.length} 条结果</div>{results.map(({date,story})=><button key={story.id} onClick={()=>jump(date,story)}><span><small>{date==="today"?"今天":date} · {story.section}</small><b>{story.title}</b><em>{story.summary}</em></span><ChevronRight size={19}/></button>)}{!results.length&&<p>没有找到相关归档</p>}</div>}</section>
{active!=="今日"&&active!=="收藏"&&<section className="date-wrap"><div className="date-list date-accordion">{dates.map(d=>{const dayStories=d.key==="today"?contentToday:contentArchives[d.key]||[],isOpen=dateOpen&&selectedDate===d.key;return <div className="date-accordion-item" data-date-key={d.key} key={d.key}><button className={isOpen?"selected":""} onClick={()=>{if(isOpen)setDateOpen(false);else{setSelectedDate(d.key);setDateOpen(true);setExpanded(null);setAppliedDateFrom("");setAppliedDateTo("");setDateFrom("");setDateTo("")}}}><span className="date-icon"><CalendarDays size={20}/></span><span><b>{d.label}</b><small>{d.sub} · {dayStories.filter(s=>s.section===active).length} 篇精选</small></span>{isOpen?<ChevronUp size={18}/>:<ChevronDown size={18}/>}</button>{isOpen&&<div className="date-expanded-content">{knowledgeView}{feedView}</div>}</div>})}</div></section>}
{(active==="今日"||active==="收藏"||appliedDateFrom)&&<>{!appliedDateFrom&&knowledgeView}{feedView}</>}
 {selectionMenu&&<button className="reading-selection" style={{left:selectionMenu.x,top:selectionMenu.y}} onMouseDown={e=>e.preventDefault()} onClick={()=>startReading()}><Volume2 size={16}/>从这里阅读</button>}{readingBarVisible&&reading!=="idle"&&<div className="reading-bar" role="status"><div className="reading-status"><Volume2 size={18}/><span>{reading==="loading"?"首次加载甜美女声…":reading==="done"?"朗读完成":reading==="paused"?"已暂停":"正在朗读"}</span><small>{readingSpeed==="slow"?"慢速":readingSpeed==="fast"?"快速":"标准速度"}</small></div><div className="reading-options" aria-label="朗读速度"><div className="reading-option-group"><span>速度</span><div><button className={readingSpeed==="slow"?"active":""} onClick={()=>updateReadingSpeed("slow")}>慢</button><button className={readingSpeed==="normal"?"active":""} onClick={()=>updateReadingSpeed("normal")}>标准</button><button className={readingSpeed==="fast"?"active":""} onClick={()=>updateReadingSpeed("fast")}>快</button></div></div></div>{reading!=="done"&&<button aria-label={reading==="paused"?"继续朗读":"暂停朗读"} onClick={toggleReading}>{reading==="paused"?<Play size={18}/>:<Pause size={18}/>}</button>}<button aria-label="停止朗读" onClick={stopReading}><Square size={16}/></button></div>}<footer><a className="brand" href="#top">Stellar AI</a><p>每天 15 分钟，看懂 AI 与世界。</p><p>历史内容持续归档</p></footer></main>
